package vim

import (
	"fmt"
	"io"
	"strings"
)

func Encode(
	w io.Writer,
	t Theme,
) error {
	var b strings.Builder

	fmt.Fprintf(
		&b,
		"\" Generated by quiet port vim. Do not edit.\n"+
			"\"\n"+
			"\" %s\n\n",
		t.Name,
	)

	fmt.Fprintf(
		&b,
		"set background=%s\n"+
			"highlight clear\n"+
			"if exists('syntax_on')\n"+
			"  syntax reset\n"+
			"endif\n"+
			"let g:colors_name = '%s'\n\n",
		t.Background,
		t.Name,
	)

	b.WriteString(
		"let g:terminal_ansi_colors = [\n",
	)

	for i, value := range t.ANSI {
		hex, err := value.Hex()
		if err != nil {
			return fmt.Errorf(
				"ANSI %d: %w",
				i,
				err,
			)
		}

		fmt.Fprintf(
			&b,
			"      \\ '%s'%s\n",
			hex,
			comma(i, len(t.ANSI)),
		)
	}

	b.WriteString(
		"      \\ ]\n\n",
	)

	for _, h := range t.Highlights {
		fg := "NONE"

		if h.Foreground != nil {
			value, err := h.Foreground.Hex()
			if err != nil {
				return fmt.Errorf(
					"%s foreground: %w",
					h.Name,
					err,
				)
			}

			fg = value
		}

		bg := "NONE"

		if h.Background != nil {
			value, err := h.Background.Hex()
			if err != nil {
				return fmt.Errorf(
					"%s background: %w",
					h.Name,
					err,
				)
			}

			bg = value
		}

		fmt.Fprintf(
			&b,
			"highlight %-18s cterm=NONE ctermfg=%-4s ctermbg=%-4s gui=NONE guifg=%-7s guibg=%-7s\n",
			h.Name,
			h.CTermForeground,
			h.CTermBackground,
			fg,
			bg,
		)
	}

	b.WriteString("\n")

	for _, link := range t.Links {
		fmt.Fprintf(
			&b,
			"highlight! link %-18s %s\n",
			link.From,
			link.To,
		)
	}

	if _, err := io.WriteString(
		w,
		b.String(),
	); err != nil {
		return fmt.Errorf(
			"write Vim colorscheme: %w",
			err,
		)
	}

	return nil
}

func comma(
	index int,
	length int,
) string {
	if index == length-1 {
		return ""
	}

	return ","
}
